Yes please!

Workarounds for this are extremely annoying to have to do:
```
- name: Add subuid/subgid entries for {{ ansible_username }} user because the user module doesn't handle this (yet)
  # See https://github.com/ansible/ansible/issues/68199
  block:
    - name: Get {{ subuid_file }} contents
      command: cat {{ subuid_file }}
      register: subuid
      changed_when: False

    - name: Add {{ ansible_username }} user to {{ subuid_file }}
      block:
        - name: Add ansible as first user to {{ subuid_file }}
          command: usermod -v 100000-165535 {{ ansible_username }}
          when: subuid.stdout | trim | length == 0

        - block:
            - set_fact:
                highest_subuid: "{{ subuid.stdout_lines[-1].split(':')[1] }}"

            - name: Add {{ ansible_username }} to list of users in {{ subuid_file }}
              command: usermod -v {{ highest_subuid|int + 65536 }}-{{ highest_subuid|int + 65536 + 65536 -1 }} {{ ansible_username }}
          when: subuid.stdout | trim | length > 0
      when: "'{{ ansible_username }}:' not in subuid.stdout"

    - name: Get {{ subgid_file }} contents
      command: cat {{ subgid_file }}
      register: subgid
      changed_when: False

    - name: Add {{ ansible_username }} user to {{ subgid_file }}
      block:
        - name: Add {{ ansible_username }} as first user to {{ subgid_file }}
          command: usermod -w 100000-165535 {{ ansible_username }}
          when: subgid.stdout | trim | length == 0

        - block:
            - set_fact:
                highest_subgid: "{{ subgid.stdout_lines[-1].split(':')[1] }}"

            - name: Add {{ ansible_username }} to list of users in {{ subgid_file }}
              command: usermod -w {{ highest_subgid|int + 65536 }}-{{ highest_subgid|int + 65536 + 65536 -1 }} {{ ansible_username }}
          when: subgid.stdout | trim | length > 0
      when: "'{{ ansible_username }}:' not in subgid.stdout"
```
